#![cfg(kani)]

#[allow(unused_imports)]
use qedgen_kani_prelude::{mul_div_ceil_u128, mul_div_floor_u128, mul_div_round_half_up_u128};

// ============================================================================
// State model (derived from qedspec — no framework dependencies)
// ============================================================================

const BPS_DENOM: u16 = 10000;

#[derive(Clone, Copy)]
struct State {
    pool: u64,
    fees: u64,
    fee_bps: u64,
    lifetime_collected: u64,
}

// ============================================================================
// Transition functions (from qedspec operations — effects + guards)
//
// Each returns true if the guard passes and the transition fires,
// false if the guard rejects the operation.
// ============================================================================

fn collect(s: &mut State, total: u64) -> bool {
    if !(total > 0 && net > 0) {
        return false;
    }
    let fee =
        (mul_div_floor_u128(((total) as u128), ((s.fee_bps) as u128), ((10000) as u128))) as u64;
    let net = total - fee;
    match s.pool.checked_add(net) {
        Some(__v) => s.pool = __v,
        None => return false,
    }
    match s.fees.checked_add(fee) {
        Some(__v) => s.fees = __v,
        None => return false,
    }
    s.lifetime_collected = s.lifetime_collected + (total);
    true
}

// ============================================================================
// Guard enforcement — transitions reject invalid inputs
// ============================================================================

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_collect_rejects_invalid() {
    let mut s = State {
        pool: kani::any(),
        fees: kani::any(),
        fee_bps: kani::any(),
    };
    let total: u64 = kani::any();
    kani::assume(!(total > 0 && net > 0));
    kani::cover!(true, "guard-violation domain is satisfiable");
    assert!(
        !collect(&mut s, total),
        "collect must reject when guard is violated"
    );
}

